};

const ALL_ROLES = Object.keys(ROLES);

const ALLOWED_SUB_ROLES = [
    'LAB_TECHNICIAN',
    'SAMPLE_RECEPTION',
    'AUDIT_USER',
    'EXTERNAL_VIEWER',
    'VIEWER',
    'SURVEYOR'
];

/**
