    ],
    'VIEW_AUDIT': [
        'SUPER_ADMIN', 'MASTER_USER', 'LAB_MANAGER', 'AUDIT_USER'
    ],

    // Help & Knowledge Base
    'HELP_READ': [
        'SUPER_ADMIN', 'MASTER_USER', 'PROJECT_MANAGER', 'LAB_MANAGER',
        'SAMPLE_RECEPTION', 'LAB_TECHNICIAN', 'SURVEYOR', 'AUDIT_USER', 'EXTERNAL_VIEWER', 'VIEWER'
    ],
    'HELP_EDIT_GLOBAL': [
        'SUPER_ADMIN'
    ],
    'HELP_EDIT_LAB': [
        'SUPER_ADMIN', 'LAB_MANAGER', 'LAB_TECHNICIAN'
    ],
    'HELP_PUBLISH_GLOBAL': [
        'SUPER_ADMIN'
    ],
    'HELP_PUBLISH_LAB': [
        'SUPER_ADMIN', 'LAB_MANAGER'
    ],

    'VIEW_LAB_POLICIES': ALL_ROLES,
    'MANAGE_LAB_POLICIES': ['SUPER_ADMIN', 'LAB_MANAGER'],
    'MANAGE_CALC_TEMPLATES': ['SUPER_ADMIN', 'LAB_MANAGER'],

    // Appearance & Themes
    'MANAGE_GLOBAL_APPEARANCE': [
        'SUPER_ADMIN'
    ],
    'MANAGE_LAB_APPEARANCE': [
        'SUPER_ADMIN', 'LAB_MANAGER'
    ]
};

/**
 * Returns all granted permissions for a given role name.
 */
function getPermissionsForRole(role) {
    if (!role) return [];
    const roleUpper = role.toUpperCase();
    const granted = [];
    for (const [perm, allowedRoles] of Object.entries(PERMISSIONS)) {
        if (allowedRoles.includes(roleUpper)) {
            granted.push(perm);
        }
    }
    return granted;
}

/**
 * Checks if a user has a specific permission key.
 */
function hasPermission(user, permission) {
    if (!user || !user.role) return false;
    const allowed = PERMISSIONS[permission];
    if (!allowed) return false;
    return allowed.includes(user.role.toUpperCase());
}

module.exports = {
    ROLES,
    ALL_ROLES,
    ALLOWED_SUB_ROLES,
    PERMISSIONS,
    getPermissionsForRole,
    hasPermission
};

